diff --git a/src/checkout.ts b/src/checkout.ts
index 2159890..5378720 100644
--- a/src/checkout.ts
+++ b/src/checkout.ts
@@ -4,3 +4,12 @@ export async function checkout(order: Order): Promise<string> {
   await saveOrder(order);
   return `order ${order.id} placed`;
 }
+
+export async function checkoutAll(orders: Order[]): Promise<string[]> {
+  const placed: string[] = [];
+  for (const order of orders) {
+    saveOrder(order);
+    placed.push(order.id);
+  }
+  return placed;
+}
