@@ -9,9 +9,10 @@ const saved = new Map<string, Order>();
 export async function saveOrder(order: Order): Promise<void> {
   if (order.items.length === 0) throw new Error(`order ${order.id} has no items`);
   await new Promise((resolve) => setTimeout(resolve, 10));
-  saved.set(order.id, order);
+  saved.set(order.id, { ...order, items: [...order.items] });
 }

 export function findOrder(id: string): Order | undefined {
-  return saved.get(id);
+  const order = saved.get(id);
+  return order && { ...order, items: [...order.items] };
